mapper.select:
SELECT FROM article a INNER JOIN follow f ON f.followed_id = a.author_id INNER JOIN article_revision r ON r.id = a.published_revision_id AND r.article_id = a.id WHERE f.follower_id = #{userId} AND a.visibility_state = 'PUBLIC' AND a.is_deleted = 0 AND a.author_id <> #{excludedAuthorId}
AND a.id NOT IN
#{shownArticleId}
ORDER BY a.create_time DESC, a.id DESC LIMIT #{limit}

SELECT DISTINCT 
FROM article a
INNER JOIN article_revision r ON r.id=a.published_revision_id AND r.article_id=a.id
CROSS JOIN JSON_TABLE(
    r.tags_json,
    '$[*]' COLUMNS(tag_name VARCHAR(64) PATH '$')
) AS revision_tag
WHERE revision_tag.tag_name IN

    #{tagName}

  AND a.visibility_state='PUBLIC'
  AND a.is_deleted=0
  AND a.author_id<>#{excludedAuthorId}

  AND a.id NOT IN

    #{shownArticleId}


ORDER BY a.create_time DESC,a.id DESC
LIMIT #{limit}

SELECT FROM article a INNER JOIN article_revision r ON r.id = a.published_revision_id AND r.article_id = a.id WHERE a.visibility_state = 'PUBLIC' AND a.is_deleted = 0 AND a.author_id <> #{excludedAuthorId}
AND a.id NOT IN
#{shownArticleId}
ORDER BY (a.create_time >= DATE_SUB(NOW(), INTERVAL 7 DAY)) DESC, (COALESCE(a.view_count, 0) + COALESCE(a.like_count, 0) * 3 + COALESCE(a.collect_count, 0) * 5 + COALESCE(a.comment_count, 0) * 4) DESC, a.create_time DESC, a.id DESC LIMIT #{limit}

SELECT FROM article a INNER JOIN article_revision r ON r.id = a.published_revision_id AND r.article_id = a.id WHERE a.id IN
#{articleId}
AND a.visibility_state = 'PUBLIC' AND a.is_deleted = 0

SELECT FROM article a INNER JOIN article_revision r ON r.id = a.published_revision_id AND r.article_id = a.id WHERE a.visibility_state = 'PUBLIC' AND a.is_deleted = 0
AND (a.create_time < #{beforeCreateTime} OR (a.create_time = #{beforeCreateTime} AND a.id < #{beforeId}))
ORDER BY a.create_time DESC, a.id DESC LIMIT #{limit}

SELECT 
FROM article a
INNER JOIN article_revision r ON r.id=a.published_revision_id AND r.article_id=a.id
WHERE a.visibility_state='PUBLIC' AND a.is_deleted=0 AND a.create_time>=#{since}
ORDER BY a.view_count DESC, a.id DESC
LIMIT #{limit}

SELECT a.*
FROM article a
INNER JOIN follow f ON f.followed_id=a.author_id
WHERE f.follower_id=#{userId} AND a.status=1 AND a.is_deleted=0
  AND a.author_id<>#{excludedAuthorId}

  AND a.id NOT IN

    #{shownArticleId}


ORDER BY a.create_time DESC, a.id DESC
LIMIT #{limit}

SELECT DISTINCT a.*
FROM article a
INNER JOIN article_tag at ON at.article_id=a.id
WHERE at.tag_id IN
#{tagId}
  AND a.status=1 AND a.is_deleted=0 AND a.author_id<>#{excludedAuthorId}

  AND a.id NOT IN

    #{shownArticleId}


ORDER BY a.create_time DESC, a.id DESC
LIMIT #{limit}

SELECT a.*
FROM article a
WHERE a.status=1 AND a.is_deleted=0 AND a.author_id<>#{excludedAuthorId}

  AND a.id NOT IN

    #{shownArticleId}


ORDER BY (a.create_time>=DATE_SUB(NOW(), INTERVAL 7 DAY)) DESC,
         (COALESCE(a.view_count,0)+COALESCE(a.like_count,0)*3
            +COALESCE(a.collect_count,0)*5+COALESCE(a.comment_count,0)*4) DESC,
         a.create_time DESC,a.id DESC
LIMIT #{limit}

SELECT a.* FROM article a
WHERE a.status=1 AND a.is_deleted=0

  AND (a.create_time<#{beforeCreateTime}
       OR (a.create_time=#{beforeCreateTime} AND a.id<#{beforeId}))

ORDER BY a.create_time DESC,a.id DESC LIMIT #{limit}

SELECT a.id FROM article a
WHERE a.status=1 AND a.is_deleted=0
ORDER BY a.create_time DESC,a.id DESC LIMIT #{limit}

SELECT a.* FROM article a
WHERE a.author_id=#{authorId} AND a.status=1 AND a.is_deleted=0
ORDER BY a.create_time DESC,a.id DESC LIMIT #{offset},#{limit}

SELECT a.* FROM article a
WHERE a.status=1 AND a.is_deleted=0 AND a.create_time>=#{since}
ORDER BY a.view_count DESC,a.id DESC LIMIT #{limit}

SELECT a.*
FROM article a
WHERE a.id = #{articleId}
  AND a.author_id = #{authorId}
  AND a.is_deleted = 0
LIMIT 1

SELECT a.* FROM article a
WHERE a.author_id=#{authorId} AND a.status=0 AND a.is_deleted=0
ORDER BY a.create_time DESC,a.id DESC LIMIT #{offset},#{limit}

SELECT a.* FROM article a
WHERE a.author_id=#{authorId} AND a.is_deleted=0
ORDER BY a.create_time DESC,a.id DESC LIMIT #{offset},#{limit}
